"""Fit fixed ISAS reference and sensor extrinsics using Walk1 only.

Walk2/3 are never fitted; output diagnostics expose calibration limitations.
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path

import numpy as np
from scipy.optimize import least_squares, minimize_scalar
from scipy.spatial.transform import Rotation, Slerp

# Published body-frame IMU-to-tag translation, identical in all three configs.
IMU_TAG_M = np.array([0.1, -0.025, 0.0])


def read_csv(path):
    """Load a named numeric CSV generated by export_isas.py."""
    return np.genfromtxt(path, delimiter=",", names=True)


def load_sequence(path):
    """Load training observations with their native timestamps and frames."""
    imu = read_csv(path / "imu.csv")
    radio = read_csv(path / "radio.csv")
    anchors = read_csv(path / "anchors.csv")
    gt = read_csv(path / "score" / "ground_truth_native.csv")
    poses = np.column_stack([gt[name] for name in ("x", "y", "z")])
    quats = Rotation.from_quat(np.column_stack([gt[name] for name in ("qx", "qy", "qz", "qw")]))
    return imu, radio, {int(a["anchor_id"]): np.array([a["x"], a["y"], a["z"]]) for a in anchors}, gt["t"], poses, Slerp(gt["t"], quats)


def fit_gyro(imu, gt_t, slerp):
    """Estimate tracker-from-IMU rotation, gyro bias, and fixed train clock lag."""
    # A 60 ms symmetric difference suppresses VIVE sampling jitter and pose noise.
    half_window = 0.03
    times = np.arange(max(imu["t"][0], gt_t[0]) + 0.2, min(imu["t"][-1], gt_t[-1]) - 0.2, 0.04)
    tracker_rate = (slerp(times - half_window).inv() * slerp(times + half_window)).as_rotvec() / (2 * half_window)
    gyro = np.column_stack([imu[name] for name in ("gx", "gy", "gz")])

    def evaluate(lag):
        """Solve a centered Wahba problem at one fixed candidate timestamp lag."""
        measured = np.column_stack([np.interp(times + lag, imu["t"], gyro[:, j]) for j in range(3)])
        rotation, _ = Rotation.align_vectors(tracker_rate - tracker_rate.mean(axis=0), measured - measured.mean(axis=0))
        bias = measured.mean(axis=0) - rotation.inv().apply(tracker_rate.mean(axis=0))
        residual = rotation.apply(measured - bias) - tracker_rate
        return float(np.mean(residual ** 2)), rotation, bias, measured, residual

    lag_fit = minimize_scalar(lambda lag: evaluate(lag)[0], bounds=(-0.1, 0.1), method="bounded", options={"xatol": 0.0001})
    mse, rotation, bias, measured, residual = evaluate(lag_fit.x)
    centered = measured - measured.mean(axis=0)
    return rotation, bias, float(lag_fit.x), {
        "gyro_fit_component_rmse_radps": float(np.sqrt(mse)),
        "gyro_excitation_singular_values": np.linalg.svd(centered, compute_uv=False).tolist(),
        "tracker_from_imu_rotation_matrix": rotation.as_matrix().tolist(),
        "gyro_bias_radps": bias.tolist(), "imu_time_minus_vive_time_s": float(lag_fit.x),
        "gyro_fit_samples": len(times), "residual_p95_norm_radps": float(np.percentile(np.linalg.norm(residual, axis=1), 95)),
    }


def fit_world(radio, anchors, gt_t, gt_pos, slerp):
    """Fit VIVE-to-RTLS SE(3) and tracker-to-tag lever using Walk1 ranges."""
    keep = (radio["t"] >= gt_t[0]) & (radio["t"] <= gt_t[-1])
    radio = radio[keep]
    t = radio["t"]
    p = np.column_stack([np.interp(t, gt_t, gt_pos[:, j]) for j in range(3)])
    a = np.array([anchors[int(value)] for value in radio["anchor_id"]])
    qt = slerp(t)
    positions, times = [], []
    for time in np.unique(t):
        select = t == time
        if np.sum(select) < 4:
            continue
        aa, rr = a[select], radio["range_m"][select]
        lhs = 2 * (aa[1:] - aa[0])
        rhs = np.sum(aa[1:] ** 2, axis=1) - np.sum(aa[0] ** 2) - rr[1:] ** 2 + rr[0] ** 2
        initial = np.linalg.lstsq(lhs, rhs, rcond=None)[0]
        point = least_squares(lambda pos: np.linalg.norm(pos - aa, axis=1) - rr, initial, loss="soft_l1", f_scale=0.15).x
        positions.append(point)
        times.append(time)
    native = np.column_stack([np.interp(times, gt_t, gt_pos[:, j]) for j in range(3)])
    target = np.asarray(positions)
    rotation, _ = Rotation.align_vectors(target - target.mean(axis=0), native - native.mean(axis=0))
    initial = np.r_[rotation.as_rotvec(), target.mean(axis=0) - rotation.apply(native.mean(axis=0)), np.zeros(3)]

    def residual(parameters):
        """Compare corrected physical ranges against transformed VIVE tag points."""
        rotation = Rotation.from_rotvec(parameters[:3])
        tag = rotation.apply(p + qt.apply(parameters[6:9])) + parameters[3:6]
        return np.linalg.norm(tag - a, axis=1) - radio["range_m"]

    fit = least_squares(residual, initial, loss="soft_l1", f_scale=0.15, max_nfev=200)
    values = residual(fit.x)
    return fit.x, {"world_fit_success": bool(fit.success), "world_fit_ranges": len(t),
                   "world_range_rmse_m": float(np.sqrt(np.mean(values ** 2))),
                   "world_range_median_abs_m": float(np.median(np.abs(values))),
                   "world_range_p95_abs_m": float(np.percentile(np.abs(values), 95)),
                   "world_fit_parameter_jacobian_singular_values": np.linalg.svd(fit.jac, compute_uv=False).tolist()}


def main():
    """Write fixed calibration from a predeclared training recording only."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--streams", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    training = args.streams / "isas_walk1"
    imu, radio, anchors, gt_t, gt_pos, slerp = load_sequence(training)
    tracker_imu, gyro_bias, lag, gyro_diagnostics = fit_gyro(imu, gt_t, slerp)
    world, world_diagnostics = fit_world(radio, anchors, gt_t, gt_pos, slerp)
    tracker_tag = world[6:9]
    tracker_imu_lever = tracker_tag - tracker_imu.apply(IMU_TAG_M)
    result = {"training_dataset": "isas_walk1", "test_datasets": ["isas_walk2", "isas_walk3"],
              "test_pose_used_for_fitting": False, "world_fit": "robust direct absolute-range residual; no estimated filter trajectory",
              "rtls_from_vive_rotation_matrix": Rotation.from_rotvec(world[:3]).as_matrix().tolist(),
              "rtls_from_vive_translation_m": world[3:6].tolist(),
              "tracker_to_tag_in_tracker_m": tracker_tag.tolist(),
              "tracker_to_imu_in_tracker_m": tracker_imu_lever.tolist(),
              "gyro_bias_radps": gyro_bias.tolist(), "imu_time_minus_vive_time_s": lag,
              "heading_reference_status": "independent training calibration; not an author-published extrinsic",
              **gyro_diagnostics, **world_diagnostics}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
